{
  "implementation": "def solve(case):
    attempts = case["attempts"]
    max_attempts = case["max_attempts"]
    n = len(attempts)
    if n == 0:
        return {
            "decision": "continue",
            "next_attempt": 1,
            "memory_append": None
        }
    last = attempts[-1]
    if last["success"]:
        return {
            "decision": "stop",
            "next_attempt": n,
            "memory_append": None
        }
    if n >= max_attempts:
        return {
            "decision": "stop",
            "next_attempt": n,
            "memory_append": None
        }
    last_sig = last["failure_signature"]
    for i in range(n - 1):
        if attempts[i]["failure_signature"] == last_sig:
            return {
                "decision": "stop",
                "next_attempt": n,
                "memory_append": None
            }
    return {
        "decision": "continue",
        "next_attempt": n + 1,
        "memory_append": {
            "reflection": last["reflection"],
            "signature": last["failure_signature"]
        }
    }"
}
